questions.solution:
function nearlyEqual(a, b, relative = 1e-12) {
  if (a === b) return true;
  return Math.abs(a - b) <= relative * Math.max(Math.abs(a), Math.abs(b));
}

console.log(nearlyEqual(0.1 + 0.2, 0.3), nearlyEqual(1e20 + 30000, 1e20), nearlyEqual(0.3, 0.31), nearlyEqual(0, 0));

