function parseNairaToKobo(text) {
  const clean = String(text).trim().replace(/^₦\s*/, "").replaceAll(",", "");
  const match = /^(\d+)(?:\.(\d{1,2}))?$/.exec(clean);
  if (!match) throw new Error("not an amount");
  const [, naira, kobo = ""] = match;
  return Number(naira) * 100 + Number(kobo.padEnd(2, "0"));
}

for (const input of ["₦1,250.50", "1.05", "0.5", "1.005", ""]) {
  try {
    console.log(parseNairaToKobo(input));
  } catch (error) {
    console.log(error.message);
  }
}

