const naira = new Intl.NumberFormat("en-NG", { style: "currency", currency: "NGN" });

function formatKobo(kobo) {
  const big = BigInt(kobo);
  const abs = big < 0n ? -big : big;
  return naira.format(`${big < 0n ? "-" : ""}${abs / 100n}.${String(abs % 100n).padStart(2, "0")}`);
}

console.log(formatKobo(125050), formatKobo(-5), formatKobo(9007199254740993n));

