questions.solution:
function sumKobo(amounts) {
  let total = 0;
  for (const kobo of amounts) {
    if (!Number.isSafeInteger(kobo)) throw new TypeError(`not whole kobo: ${kobo}`);
    total += kobo;
    if (!Number.isSafeInteger(total)) throw new RangeError("total outside the safe range");
  }
  return total;
}

console.log(sumKobo([125050, 90000, -5]));
for (const bad of [[10.5], ["100"], [Number.MAX_SAFE_INTEGER, 1]]) {
  try {
    sumKobo(bad);
  } catch (error) {
    console.log(error.name);
  }
}

