function vatKobo(kobo, basisPoints) {
  const numerator = kobo * basisPoints;
  const quotient = Math.trunc(numerator / 10000);
  const twice = 2 * Math.abs(numerator - quotient * 10000);
  if (twice < 10000) return quotient;
  return quotient + (numerator < 0 ? -1 : 1);
}

console.log(vatKobo(2450, 750), vatKobo(2460, 750), vatKobo(0, 750));
